// Node.js script to:
// 1. Read the catalog from blessed-catalog.json
// 2. Use ole2-extractor.js (pure Node.js + iconv-lite) for DOC text extraction
// 3. Save results as library-data JSON files

const fs = require('fs');
const path = require('path');
const { extractDocText } = require('./ole2-extractor');

const SRC_BASE = 'D:\\dev\\usebible.com\\html\\blessed\\chinese\\download';
const DST_BASE = 'D:\\dev\\github\\bible-microservices\\frontend\\library-data';

// Read catalog from JSON file (generated by write-catalog.js with proper UTF-8)
const catalog = JSON.parse(fs.readFileSync(path.join(__dirname, 'blessed-catalog.json'), 'utf8'));
console.log(`Catalog: ${catalog.length} items`);


function extractRtfText(filePath) {
    // Check file format
    const buf = fs.readFileSync(filePath);
    const isOle2 = buf[0] === 0xD0 && buf[1] === 0xCF && buf[2] === 0x11 && buf[3] === 0xE0;
    const isRtf = buf.toString('latin1', 0, 5).startsWith('{\\rtf');
    
    if (isOle2) {
        // OLE2 format - use our pure Node.js extractor
        return extractDocText(filePath);
    } else if (isRtf) {
        // RTF format - use PowerShell RichTextBox (more reliable for Chinese RTF)
        const { execSync } = require('child_process');
        const outFile = filePath + '.txt';
        const env = { ...process.env, RTF_FILE: filePath, OUT_FILE: outFile };
        const psScript = path.join(__dirname, 'extract-rtf.ps1');
        try {
            execSync(`powershell -ExecutionPolicy Bypass -File "${psScript}" -RTF_FILE "${filePath}" -OUT_FILE "${outFile}"`, { env, timeout: 30000 });
            const text = fs.readFileSync(outFile, 'utf8');
            try { fs.unlinkSync(outFile); } catch(e) {}
            return text;
        } catch(e) {
            // Fallback to Node.js RTF extractor
            return extractDocText(filePath);
        }
    }
    
    // Plain text
    return buf.toString('utf8');
}

function splitChapters(text) {
    // Try pattern: 第X课/第X章/第X讲/第X篇
    const matches = [...text.matchAll(/第[一二三四五六七八九十百零\d]+[课章讲篇]/g)];
    if (matches.length > 1) {
        const chapters = [];
        for (let i = 0; i < matches.length; i++) {
            const start = matches[i].index;
            const end = i + 1 < matches.length ? matches[i+1].index : text.length;
            const title = matches[i][0];
            const content = text.substring(start, end).trim();
            if (content.length > 50) chapters.push({ title, content });
        }
        if (chapters.length > 0) return chapters;
    }
    
    // Split long text into ~3000 char sections
    if (text.length > 10000) {
        const sections = text.split(/\n\n+/).filter(s => s.trim().length > 100);
        if (sections.length > 5) {
            const chapters = [];
            let current = '';
            let chTitle = '前言';
            let chNum = 0;
            for (const sec of sections) {
                const trimmed = sec.trim();
                const isHeading = trimmed.length < 80 && /^[一二三四五六七八九十\d第]/.test(trimmed);
                if (isHeading && current.length > 500) {
                    chapters.push({ title: chTitle, content: current.trim() });
                    chNum++;
                    chTitle = trimmed.split('\n')[0];
                    current = '';
                }
                if (current.length > 3000 && !isHeading) {
                    chapters.push({ title: chTitle, content: current.trim() });
                    chNum++;
                    chTitle = `第${chNum + 1}部分`;
                    current = '';
                }
                current += trimmed + '\n\n';
            }
            if (current.trim()) chapters.push({ title: chTitle, content: current.trim() });
            if (chapters.length > 0) return chapters;
        }
    }
    
    return [{ title: '全文', content: text }];
}

// Main
console.log('=== Blessed.org DOC -> Library Import (Node+NET RTF) ===\n');

let totalFiles = 0, totalChars = 0, totalChinese = 0;
const allBooks = [];
const errors = [];

for (const item of catalog) {
    const filePath = path.join(SRC_BASE, item.dir, item.file);
    const baseName = item.file.replace('.doc', '');
    const bookCode = `bl_${baseName.replace(/-/g, '_')}`;
    
    if (!fs.existsSync(filePath)) {
        console.warn(`  SKIP: ${item.file} not found`);
        errors.push(`${item.file}: not found`);
        continue;
    }
    
    try {
        const text = extractRtfText(filePath);
        const chineseCount = (text.match(/[\u4e00-\u9fff]/g) || []).length;
        
        if (text.length < 50) {
            console.warn(`  WARN: ${item.file} -> ${bookCode}: ${text.length} chars, ${chineseCount} Chinese`);
        }
        
        const chapters = splitChapters(text);
        const outDir = path.join(DST_BASE, bookCode);
        if (!fs.existsSync(outDir)) fs.mkdirSync(outDir, { recursive: true });
        
        const meta = {
            code: bookCode,
            title: item.title,
            titleEn: item.titleEn,
            author: 'Blessed.org',
            source: 'blessed.org',
            category: item.cat,
            icon: item.icon,
            chapters: chapters.length
        };
        fs.writeFileSync(path.join(outDir, 'meta.json'), JSON.stringify(meta, null, 2), 'utf8');
        
        for (let i = 0; i < chapters.length; i++) {
            fs.writeFileSync(path.join(outDir, `${i+1}.json`), JSON.stringify({
                id: i + 1, title: chapters[i].title, content: chapters[i].content
            }, null, 2), 'utf8');
        }
        
        totalFiles++;
        totalChars += text.length;
        totalChinese += chineseCount;
        allBooks.push({
            code: bookCode, title: item.title, titleEn: item.titleEn,
            author: 'Blessed.org', category: item.cat, icon: item.icon,
            chapters: chapters.length, source: 'blessed.org'
        });
        console.log(`  OK: ${item.file} -> ${bookCode}: ${chapters.length}ch, ${text.length}chars, ${chineseCount} CN`);
    } catch(e) {
        console.error(`  ERROR: ${item.file} - ${e.message}`);
        errors.push(`${item.file}: ${e.message}`);
    }
}

// Merge with existing index
let existingBooks = [];
try {
    const existing = JSON.parse(fs.readFileSync(path.join(DST_BASE, 'index.json'), 'utf8'));
    existingBooks = (existing.books || []).filter(b => !b.code.startsWith('bl_'));
} catch(e) {}

const merged = [...existingBooks, ...allBooks];
fs.writeFileSync(path.join(DST_BASE, 'index.json'), JSON.stringify({
    totalBooks: merged.length,
    totalChapters: merged.reduce((s, b) => s + (b.chapters || 0), 0),
    books: merged
}, null, 2), 'utf8');

console.log(`\n=== Summary ===`);
console.log(`Files: ${totalFiles}, Chars: ${totalChars}, Chinese: ${totalChinese}`);
console.log(`Library: ${merged.length} books, ${merged.reduce((s,b)=>s+(b.chapters||0),0)} chapters`);
if (errors.length) console.log(`Errors: ${errors.length}`, errors);
console.log('Done!');
